// Package storage keeps binary files (image originals and thumbnails) on the
// local filesystem under DATA_DIR (ARCHITECTURE §4). Callers address files by
// a storage key such as `images/3f/a2/<uuid>.png`. Keys are generated by the
// server, never derived from user input, but the store still refuses anything
// that could leave DATA_DIR: it works through an os.Root, which rejects `..`
// and symbolic links that point outside.
package storage

import (
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path"
	"strings"
	"time"

	"github.com/google/uuid"
)

// ErrNotFound is returned by Open when the key has no file.
var ErrNotFound = errors.New("storage: file not found")

// ErrInvalidKey is returned for a key that is not a clean relative path.
var ErrInvalidKey = errors.New("storage: invalid key")

// FileStore stores files by key. Implementations must be safe for concurrent use.
type FileStore interface {
	// Put writes r to key. The file appears under key only when it is complete:
	// it is written to a temporary file next to it and renamed. Returns the
	// number of bytes written.
	Put(key string, r io.Reader) (int64, error)
	// Open returns the file and its size. A missing file is ErrNotFound.
	Open(key string) (io.ReadCloser, int64, error)
	// Delete removes the file. A missing file is not an error (retries are safe).
	Delete(key string) error
	// Walk calls fn for every file under the prefix directory (for example
	// "images"), including leftover temporary files, with its modification time.
	// A missing prefix directory is an empty walk.
	Walk(prefix string, fn func(key string, modTime time.Time) error) error
}

// Local is a FileStore on a directory of the local filesystem.
type Local struct {
	root *os.Root
}

var _ FileStore = (*Local)(nil)

// NewLocal opens dir (which must exist) as the store root.
func NewLocal(dir string) (*Local, error) {
	root, err := os.OpenRoot(dir)
	if err != nil {
		return nil, fmt.Errorf("open storage root: %w", err)
	}
	return &Local{root: root}, nil
}

// Close releases the root directory handle.
func (l *Local) Close() error { return l.root.Close() }

// Put implements FileStore.
func (l *Local) Put(key string, r io.Reader) (n int64, err error) {
	if err := validKey(key); err != nil {
		return 0, err
	}
	dir := path.Dir(key)
	if err := l.root.MkdirAll(dir, 0o750); err != nil {
		return 0, fmt.Errorf("storage: create directory: %w", err)
	}
	tmp := path.Join(dir, ".tmp-"+uuid.NewString())
	f, err := l.root.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		return 0, fmt.Errorf("storage: create temporary file: %w", err)
	}
	defer func() {
		if err != nil {
			_ = f.Close()
			_ = l.root.Remove(tmp)
		}
	}()
	if n, err = io.Copy(f, r); err != nil {
		return 0, fmt.Errorf("storage: write file: %w", err)
	}
	if err = f.Sync(); err != nil {
		return 0, fmt.Errorf("storage: sync file: %w", err)
	}
	if err = f.Close(); err != nil {
		return 0, fmt.Errorf("storage: close file: %w", err)
	}
	if err = l.root.Rename(tmp, key); err != nil {
		return 0, fmt.Errorf("storage: publish file: %w", err)
	}
	return n, nil
}

// Open implements FileStore.
func (l *Local) Open(key string) (io.ReadCloser, int64, error) {
	if err := validKey(key); err != nil {
		return nil, 0, err
	}
	f, err := l.root.Open(key)
	if errors.Is(err, fs.ErrNotExist) {
		return nil, 0, ErrNotFound
	}
	if err != nil {
		return nil, 0, fmt.Errorf("storage: open file: %w", err)
	}
	fi, err := f.Stat()
	if err != nil {
		_ = f.Close()
		return nil, 0, fmt.Errorf("storage: stat file: %w", err)
	}
	return f, fi.Size(), nil
}

// Delete implements FileStore.
func (l *Local) Delete(key string) error {
	if err := validKey(key); err != nil {
		return err
	}
	if err := l.root.Remove(key); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return fmt.Errorf("storage: delete file: %w", err)
	}
	return nil
}

// Walk implements FileStore.
func (l *Local) Walk(prefix string, fn func(key string, modTime time.Time) error) error {
	if err := validKey(prefix); err != nil {
		return err
	}
	if _, err := l.root.Stat(prefix); errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	return fs.WalkDir(l.root.FS(), prefix, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			return nil
		}
		info, err := d.Info()
		if err != nil {
			if errors.Is(err, fs.ErrNotExist) {
				return nil // deleted while walking
			}
			return err
		}
		if !info.Mode().IsRegular() {
			return nil
		}
		return fn(p, info.ModTime())
	})
}

// validKey accepts only clean, relative, slash-separated keys whose segments
// are made of letters, digits, `.`, `_` and `-`.
func validKey(key string) error {
	if key == "" || key != path.Clean(key) || strings.HasPrefix(key, "/") {
		return ErrInvalidKey
	}
	for _, seg := range strings.Split(key, "/") {
		if seg == "" || seg == "." || seg == ".." {
			return ErrInvalidKey
		}
		for _, c := range seg {
			ok := c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '.' || c == '_' || c == '-'
			if !ok {
				return ErrInvalidKey
			}
		}
	}
	return nil
}
